package com.example.starter.rosbag.util;

import java.nio.charset.StandardCharsets;
import java.util.zip.CRC32;

/**
 * 负载与段级校验统一使用 CRC32，结果按无符号 32 位存入 long。
 */
public final class Checksums {

    private Checksums() {
    }

    /**
     * 计算文本负载的 CRC32 校验值。
     */
    public static long crc32(String text) {
        CRC32 crc = new CRC32();
        crc.update(text.getBytes(StandardCharsets.UTF_8));
        return crc.getValue();
    }

    /**
     * 将一条消息并入段级滚动校验：依次纳入 topic、seq、纳秒时间戳、类型与负载校验值。
     */
    public static long foldMessage(long partial, String topic, long seq, long timestampNs,
                                   String typeId, long payloadChecksum) {
        CRC32 crc = new CRC32();
        crc.update(longToBytes(partial));
        crc.update(topic.getBytes(StandardCharsets.UTF_8));
        crc.update(longToBytes(seq));
        crc.update(longToBytes(timestampNs));
        crc.update(typeId.getBytes(StandardCharsets.UTF_8));
        crc.update(longToBytes(payloadChecksum));
        return crc.getValue();
    }

    private static byte[] longToBytes(long value) {
        byte[] bytes = new byte[Long.BYTES];
        for (int i = Long.BYTES - 1; i >= 0; i--) {
            bytes[i] = (byte) (value & 0xffL);
            value >>= 8;
        }
        return bytes;
    }
}

package com.example.starter.rosbag.model;

/**
 * 逻辑分段持久化对象。
 *
 * @param status OPEN=可追加；SEALED=正常封段；RECOVERED=经恢复重建后封段
 */
public record Segment(
        Long id,
        String topic,
        long segmentNo,
        Long startNs,
        Long endNs,
        Long startSeq,
        Long endSeq,
        long messageCount,
        String status,
        long segmentChecksum
) {
    public static final String OPEN = "OPEN";
    public static final String SEALED = "SEALED";
    public static final String RECOVERED = "RECOVERED";
}

package com.example.starter.rosbag.model;

/**
 * 消息持久化对象。
 *
 * @param valid true=完整可查；false=恢复时被隔离的不完整后缀消息
 */
public record Message(
        Long id,
        String topic,
        long seq,
        long timestampNs,
        String typeId,
        String payload,
        long payloadChecksum,
        String batchNo,
        long segmentId,
        boolean valid
) {
}

package com.example.starter.rosbag.model;

/**
 * 回放记录持久化对象，相同 replayKey 只能存在一条。
 */
public record ReplayRecord(
        Long id,
        String replayKey,
        String topic,
        Long fromNs,
        Long toNs,
        long messageCount,
        long createdAtNs
) {
}

