package com.example.starter.rosbag.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 单条消息写入请求。batchNo 用于同参重试幂等。
 */
public record WriteMessageRequest(
        @NotBlank String topic,
        @NotNull Long seq,
        @NotNull Long timestampNs,
        @NotBlank String typeId,
        @NotNull String payload,
        @NotBlank String batchNo
) {
}

package com.example.starter.rosbag.dto;

/**
 * 写入结果。deduplicated=true 表示该批次已存在，本次为重试，未重复写入。
 */
public record WriteResult(
        String topic,
        long seq,
        long segmentId,
        long segmentNo,
        String batchNo,
        long payloadChecksum,
        boolean deduplicated
) {
}

package com.example.starter.rosbag.dto;

/**
 * 组合查询条件；所有边界均可空（null 表示不限制），均为闭区间。
 */
public record QueryRequest(
        String topic,
        Long fromNs,
        Long toNs,
        Long fromSeq,
        Long toSeq
) {
}

package com.example.starter.rosbag.dto;

/**
 * 查询命中的消息视图，按 (timestamp_ns, seq) 原顺序返回。
 */
public record MessageView(
        long id,
        String topic,
        long seq,
        long timestampNs,
        String typeId,
        String payload,
        long payloadChecksum,
        String batchNo,
        long segmentId
) {
}

package com.example.starter.rosbag.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 按原顺序回放请求；replayKey 相同的重复请求不会重复创建回放记录。
 */
public record ReplayRequest(
        @NotBlank String replayKey,
        @NotBlank String topic,
        Long fromNs,
        Long toNs
) {
}

package com.example.starter.rosbag.dto;

import java.util.List;

/**
 * 回放结果。deduplicated=true 表示回放记录已存在，消息按原顺序重新返回但不新建记录。
 */
public record ReplayResult(
        String replayKey,
        boolean deduplicated,
        long messageCount,
        List<MessageView> messages
) {
}

package com.example.starter.rosbag.dto;

import java.util.List;

/**
 * 恢复结果：保留前缀、隔离尾部消息、删除并重建索引的统计。
 */
public record RecoveryResult(
        String topic,
        long segmentsScanned,
        long prefixMessagesKept,
        long incompleteMessagesQuarantined,
        long indexRowsRebuilt,
        List<SegmentView> segments
) {
}

package com.example.starter.rosbag.dto;

/**
 * 分段元数据视图。
 */
public record SegmentView(
        long id,
        String topic,
        long segmentNo,
        Long startNs,
        Long endNs,
        Long startSeq,
        Long endSeq,
        long messageCount,
        String status,
        long segmentChecksum
) {
}

