package com.example.starter.rosbag.exception;

/**
 * rosbag 业务异常基类，映射为 HTTP 409。
 */
public class RosbagException extends RuntimeException {

    public RosbagException(String message) {
        super(message);
    }
}

package com.example.starter.rosbag.exception;

/**
 * Topic 内序列号倒退（新消息 seq 不大于当前最大有效 seq）。
 */
public class SequenceRegressionException extends RosbagException {

    public SequenceRegressionException(String topic, long requestedSeq, long maxSeq) {
        super("topic " + topic + " 序列号倒退：请求 seq=" + requestedSeq + "，当前最大 seq=" + maxSeq);
    }
}

package com.example.starter.rosbag.exception;

/**
 * 同一写入批次号携带了与首次写入不同的参数。
 */
public class BatchConflictException extends RosbagException {

    public BatchConflictException(String batchNo) {
        super("批次号 " + batchNo + " 已存在但参数不一致，拒绝写入");
    }
}

package com.example.starter.rosbag.time;

/**
 * 可替换的时间源，返回纳秒级绝对时间（UTC 纪元）；测试可提供可控实现。
 */
public interface TimeSource {

    long nowEpochNs();
}

package com.example.starter.rosbag.time;

import org.springframework.stereotype.Component;

/**
 * 基于墙钟的默认时间源：毫秒级精度放大到纳秒。
 */
@Component
public class SystemTimeSource implements TimeSource {

    @Override
    public long nowEpochNs() {
        return System.currentTimeMillis() * 1_000_000L;
    }
}

