        }
        String status = changed ? Segment.RECOVERED : segment.status();
        segmentRepository.updateAggregatesAndStatus(segment.id(), startNs, endNs, startSeq, endSeq,
                kept.size(), checksum, status);
    }

    private boolean metadataDiffers(Segment stored, List<Message> actual, long actualChecksum) {
        if (stored.messageCount() != actual.size() || stored.segmentChecksum() != actualChecksum) {
            return true;
        }
        if (actual.isEmpty()) {
            return stored.startNs() != null || stored.endNs() != null
                    || stored.startSeq() != null || stored.endSeq() != null;
        }
        long startNs = actual.stream().mapToLong(Message::timestampNs).min().orElseThrow();
        long endNs = actual.stream().mapToLong(Message::timestampNs).max().orElseThrow();
        long startSeq = actual.stream().mapToLong(Message::seq).min().orElseThrow();
        long endSeq = actual.stream().mapToLong(Message::seq).max().orElseThrow();
        return stored.startNs() == null || stored.startNs() != startNs
                || stored.endNs() == null || stored.endNs() != endNs
                || stored.startSeq() == null || stored.startSeq() != startSeq
                || stored.endSeq() == null || stored.endSeq() != endSeq;
    }

    /**
     * 恢复完成后保证存在可写 OPEN 段：
     * 末个仍有消息的段若原本就是 OPEN，则继续作为可写段；否则在最大段号之后新建 OPEN 段。
     */
    private void restoreOpenSegment(String topic, List<Segment> segments, Segment liveSegment) {
        if (liveSegment != null && Segment.OPEN.equals(liveSegment.status())) {
            Segment reloaded = segmentRepository.findByIdForUpdate(liveSegment.id());
            if (reloaded != null && Segment.RECOVERED.equals(reloaded.status())) {
                // 前缀段被重算过：保留 RECOVERED 元数据形态的同时承接追加不便于区分，
                // 因此统一另开新 OPEN 段，前缀段以 RECOVERED 固化。
                createOpenAfter(topic, segments);
            }
            return;
        }
        createOpenAfter(topic, segments);
    }

    private void createOpenAfter(String topic, List<Segment> segments) {
        long maxNo = segments.stream().mapToLong(Segment::segmentNo).max().orElse(-1L);
        Segment existingOpen = segmentRepository.findOpenForUpdate(topic);
        if (existingOpen == null) {
            segmentRepository.createOpen(topic, maxNo + 1);
        }
    }

    private void emptySegmentAsRecovered(Segment segment, String reason) {
        // 保留段行作为现场，边界清空、状态 RECOVERED
        segmentRepository.updateAggregatesAndStatus(segment.id(), null, null, null, null,
                0L, 0L, Segment.RECOVERED);
    }

    /**
     * 列出某 Topic 的分段元数据。
     */
    @Transactional(readOnly = true)
    public List<SegmentView> segments(String topic) {
        return segmentRepository.findByTopic(topic).stream().map(this::toView).toList();
    }

    private SegmentView toView(Segment segment) {
        return new SegmentView(segment.id(), segment.topic(), segment.segmentNo(),
                segment.startNs(), segment.endNs(), segment.startSeq(), segment.endSeq(),
                segment.messageCount(), segment.status(), segment.segmentChecksum());
    }
}

