    id 'org.springframework.boot' version '3.5.16'
}

group = 'com.example'
version = '0.1.0'

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

repositories {
    mavenCentral()
}

dependencies {
    implementation platform('org.springframework.boot:spring-boot-dependencies:3.5.16')
    implementation 'org.springframework.boot:spring-boot-starter-web'
    implementation 'org.springframework.boot:spring-boot-starter-validation'
    implementation 'org.springframework.boot:spring-boot-starter-jdbc'
    implementation 'org.springframework.boot:spring-boot-starter-actuator'
    runtimeOnly 'com.h2database:h2'
    runtimeOnly 'com.mysql:mysql-connector-j'
    testImplementation 'org.springframework.boot:spring-boot-starter-test'
    testRuntimeOnly 'com.h2database:h2'
}

tasks.withType(JavaCompile).configureEach {
    options.encoding = 'UTF-8'
}

tasks.named('test') {
    useJUnitPlatform()
    // Windows 非 ASCII 项目路径下，fork 的测试 JVM 默认按系统 ANSI（GBK）解码启动参数，
    // 会使含中文的类路径条目失效。统一指定 UTF-8 并使用 ASCII 工作目录。
    systemProperty 'file.encoding', 'UTF-8'
    systemProperty 'sun.jnu.encoding', 'UTF-8'
    environment 'JAVA_TOOL_OPTIONS', '-Dfile.encoding=UTF-8 -Dsun.jnu.encoding=UTF-8'
    def asciiWorkDir = layout.buildDirectory.dir('test-work').get().asFile
    doFirst { asciiWorkDir.mkdirs() }
    workingDir = asciiWorkDir
}

tasks.named('bootJar') {
    archiveFileName = 'app.jar'
}

tasks.named('jar') {
    enabled = false
}

// 临时诊断：定位测试 worker 启动环境
println "DIAG java.version=" + System.getProperty('java.version')
println "DIAG file.encoding=" + System.getProperty('file.encoding')
println "DIAG sun.jnu.encoding=" + System.getProperty('sun.jnu.encoding')
println "DIAG java.io.tmpdir=" + System.getProperty('java.io.tmpdir')
println "DIAG user.dir=" + System.getProperty('user.dir')
println "DIAG JAVA_HOME=" + System.getenv('JAVA_HOME')
println "DIAG GRADLE_USER_HOME=" + System.getenv('GRADLE_USER_HOME')
println "DIAG gradleHome=" + gradle.gradleHomeDir

def probeJava = { String cp, String label ->
    def out = new ByteArrayOutputStream()
    def err = new ByteArrayOutputStream()
    try {
        exec {
            executable = org.gradle.internal.jvm.Jvm.current().javaExecutable
            args = ['-cp', cp, 'worker.org.gradle.process.internal.worker.GradleWorkerMain']
            standardOutput = out
            errorOutput = err
            ignoreExitValue = true
        }
    } catch (Exception e) {
        println "DIAG " + label + " exec-fail: " + e.message
        return
    }
    def o = out.toString('UTF-8')
    def e = err.toString('UTF-8')
    println "DIAG " + label + " OUT=[" + o.take(300) + "] ERR=[" + e.take(300) + "]"
}

def workerBootstrap = new File(gradle.gradleUserHomeDir, 'caches/8.14.4/workerMain/gradle-worker.jar')
println "DIAG workerBootstrap exists=" + workerBootstrap.exists() + " path=" + workerBootstrap.absolutePath

def jar = new java.util.jar.JarFile(workerBootstrap)
def entries = jar.entries().toList()*.name
println "DIAG bootstrap entries=" + entries.take(30)
jar.close()

probeJava(workerBootstrap.absolutePath, "bootstrap-chinese")

def asciiCopy = new File(System.getProperty('java.io.tmpdir'), 'probe-gradle-worker.jar')
java.nio.file.Files.copy(workerBootstrap.toPath(), asciiCopy.toPath(),
        java.nio.file.StandardCopyOption.REPLACE_EXISTING)
probeJava(asciiCopy.absolutePath, "bootstrap-ascii")

