def probeJava = { String cp, String label ->
    def out = new ByteArrayOutputStream()
    def err = new ByteArrayOutputStream()
    try {
        exec {
            executable = org.gradle.internal.jvm.Jvm.current().javaExecutable
            args = ['-cp', cp, 'worker.org.gradle.process.internal.worker.GradleWorkerMain']
            standardOutput = out
            errorOutput = err
            ignoreExitValue = true
        }
    } catch (Exception e) {
        println "DIAG " + label + " exec-fail: " + e.message
        return
    }
    def o = out.toString('UTF-8')
    def e = err.toString('UTF-8')
    println "DIAG " + label + " OUT=[" + o.take(300) + "] ERR=[" + e.take(300) + "]"
}

